ALTER TABLE entitlements ADD COLUMN bulk_next_at timestamptz;
CREATE TABLE bulk_campaigns(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid NOT NULL REFERENCES users(id),request_id uuid NOT NULL,content_hash text NOT NULL,payload text NOT NULL,sender_email text NOT NULL,total integer NOT NULL CHECK(total BETWEEN 1 AND 500),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','queued','running','paused','completed','cancelled')),reason text,expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,request_id),UNIQUE(workspace_id,id));
CREATE INDEX bulk_campaigns_owner ON bulk_campaigns(workspace_id,created_at DESC);
CREATE INDEX bulk_campaigns_queue ON bulk_campaigns(status,updated_at);
CREATE TABLE bulk_recipients(id uuid PRIMARY KEY,campaign_id uuid NOT NULL,workspace_id uuid NOT NULL,position integer NOT NULL,payload text NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','sending','sent','unknown','failed','cancelled')),reserved boolean NOT NULL DEFAULT false,claim_token uuid,started_at timestamptz,message_id uuid,error text,sent_at timestamptz,FOREIGN KEY(workspace_id,campaign_id) REFERENCES bulk_campaigns(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id),UNIQUE(campaign_id,position));
CREATE INDEX bulk_recipients_queue ON bulk_recipients(campaign_id,state,position);
CREATE INDEX bulk_recipients_stale ON bulk_recipients(started_at) WHERE state='sending';
